// Parses a WhatsApp Cloud API text message into an order.
// Accepted examples (Bangla or English, Bangla digits supported):
//   Name: Rahim
//   Phone: 01712345678
//   Address: House 5, Road 3, Mirpur, Dhaka
//   2 x Panjabi
//   Saree x 1
// Edit PRICES (BDT) to get an automatic total; unknown items are listed without a price.
const PRICES = { 'panjabi': 1200, 'saree': 2500, 'পাঞ্জাবি': 1200, 'শাড়ি': 2500 };

const bn = '০১২৩৪৫৬৭৮৯';
const toEn = (s) => String(s || '').replace(/[০-৯]/g, (d) => bn.indexOf(d));

const body = $input.first().json.body || $input.first().json;
const value = body?.entry?.[0]?.changes?.[0]?.value;
const msg = value?.messages?.[0];
if (!msg || msg.type !== 'text') return []; // ignore delivery/read statuses and non-text messages

const raw = msg.text.body || '';
const text = toEn(raw);
const isBangla = /[ঀ-৿]/.test(raw);

const label = (names) => {
  const m = text.match(new RegExp('(?:' + names + ')\\s*[:：\\-]\\s*(.+)', 'i'));
  return m ? m[1].trim() : '';
};
const name = label('name|নাম') || value?.contacts?.[0]?.profile?.name || '';
const phone = label('phone|mobile|contact|ফোন|মোবাইল').replace(/[^\d+]/g, '');
const address = label('address|ঠিকানা');

const items = [];
for (const line of text.split(/\r?\n|,/)) {
  const l = line.trim().replace(/^[-*•\d]+[.)]\s+/, '');
  if (!l || /^(name|phone|mobile|contact|address|নাম|ফোন|মোবাইল|ঠিকানা)\s*[:：\-]/i.test(l)) continue;
  let m = l.match(/^(.+?)\s*[x×*]\s*(\d+)\s*(?:pcs|pc|টি|পিস)?$/i);
  let item, qty;
  if (m) { item = m[1]; qty = parseInt(m[2], 10); }
  else if ((m = l.match(/^(\d+)\s*(?:pcs|pc|টি|পিস)?\s*[x×*\-]?\s*(.+)$/i))) { qty = parseInt(m[1], 10); item = m[2]; }
  else continue;
  item = item.trim();
  if (!item || !qty || qty > 500) continue;
  const unit = PRICES[item.toLowerCase()];
  items.push({ item, qty, unit: unit ?? null, line: unit != null ? unit * qty : null });
}

const valid = items.length > 0 && (address.length > 5 || phone.length >= 10);
const priced = items.filter((i) => i.line != null);
const total = priced.reduce((s, i) => s + i.line, 0);
const itemsText = items.map((i) => `${i.item} x ${i.qty}`).join('; ');
const orderId = 'ORD-' + Date.now().toString(36).toUpperCase();

const replyText = valid
  ? (isBangla
      ? `ধন্যবাদ ${name}! আপনার অর্ডার গ্রহণ করা হয়েছে।\nঅর্ডার নম্বর: ${orderId}\nপণ্য: ${itemsText}\n` +
        (priced.length ? `মোট: ৳${total}\n` : '') + `ঠিকানা: ${address || 'দেওয়া হয়নি'}\nআমরা শীঘ্রই যোগাযোগ করব।`
      : `Thank you ${name}! Your order is received.\nOrder ID: ${orderId}\nItems: ${itemsText}\n` +
        (priced.length ? `Total: BDT ${total}\n` : '') + `Address: ${address || 'not provided'}\nWe will contact you shortly.`)
  : (isBangla
      ? 'অর্ডার বোঝা যায়নি। অনুগ্রহ করে এভাবে লিখুন:\nনাম: ...\nফোন: ...\nঠিকানা: ...\n2 x পণ্যের নাম'
      : 'Sorry, I could not read your order. Please send:\nName: ...\nPhone: ...\nAddress: ...\n2 x Item name');

return [{ json: {
  orderId, valid, receivedAt: new Date().toISOString(), customerWaId: msg.from,
  phoneNumberId: value?.metadata?.phone_number_id || 'YOUR_PHONE_NUMBER_ID',
  name, phone, address, itemsText, itemCount: items.length, total: priced.length ? total : '',
  rawMessage: raw, replyText
} }];
